const ROUTE_REFRESH_METERS = 75;
const ROUTE_REFRESH_MS = 5000;
const OFFLINE_MAP_CACHE = "biyahero-offline-map-v1";
const OFFLINE_RIDER_ROUTE_KEY_PREFIX = "biyahero_offline_rider_route_";
const OFFLINE_TILE_ZOOMS = [15, 16, 17];
const OFFLINE_TILE_LIMIT = 260;

// Default center — General Santos City, Philippines
// Used as fallback when GPS/coordinates are not yet available to avoid maps rendering at [0,0]
const DEFAULT_CENTER: [number, number] = [6.1164, 125.1716];

function haversineMeters(a: [number, number], b: [number, number]): number {
  const R = 6371000;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLon = ((b[1] - a[1]) * Math.PI) / 180;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a[0] * Math.PI) / 180) *
      Math.cos((b[0] * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.asin(Math.sqrt(s));
}

function latLngToTile(lat: number, lng: number, zoom: number) {
  const latRad = (lat * Math.PI) / 180;
  const n = 2 ** zoom;
  const x = Math.floor(((lng + 180) / 360) * n);
  const y = Math.floor(
    ((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n,
  );
  return { x, y };
}

function sampleRoutePoints(
  coords: [number, number][],
  maxPoints = 28,
): [number, number][] {
  if (coords.length <= maxPoints) return coords;
  const step = Math.max(1, Math.floor(coords.length / maxPoints));
  const sampled = coords.filter((_, index) => index % step === 0);
  const last = coords[coords.length - 1];
  if (last && sampled[sampled.length - 1] !== last) sampled.push(last);
  return sampled;
}

async function cacheOfflineRouteTiles(
  coords: [number, number][],
): Promise<number> {
  if (!("caches" in window) || coords.length === 0) return 0;

  const cache = await caches.open(OFFLINE_MAP_CACHE);
  const urls = new Set<string>();
  const points = sampleRoutePoints(coords);

  for (const zoom of OFFLINE_TILE_ZOOMS) {
    for (const [lat, lng] of points) {
      const center = latLngToTile(lat, lng, zoom);
      for (let dx = -1; dx <= 1; dx++) {
        for (let dy = -1; dy <= 1; dy++) {
          urls.add(
            `https://a.tile.openstreetmap.org/${zoom}/${center.x + dx}/${center.y + dy}.png`,
          );
          if (urls.size >= OFFLINE_TILE_LIMIT) break;
        }
        if (urls.size >= OFFLINE_TILE_LIMIT) break;
      }
      if (urls.size >= OFFLINE_TILE_LIMIT) break;
    }
    if (urls.size >= OFFLINE_TILE_LIMIT) break;
  }

  const requests = [...urls];
  let cached = 0;
  await Promise.all(
    requests.map(async (url) => {
      try {
        const match = await cache.match(url);
        if (match) {
          cached += 1;
          return;
        }
        const response = await fetch(url, {
          mode: "no-cors",
          cache: "force-cache",
        });
        await cache.put(url, response);
        cached += 1;
      } catch {
        // Individual tile failures should not block the rest of the offline pack.
      }
    }),
  );
  return cached;
}

async function fetchOsrmRoute(
  from: [number, number],
  to: [number, number],
  signal?: AbortSignal,
): Promise<[number, number][] | null> {
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${from[1]},${from[0]};${to[1]},${to[0]}?overview=full&geometries=geojson`;
    const r = await fetch(url, { signal });
    const data = await r.json();
    if (data.routes?.length > 0) {
      return data.routes[0].geometry.coordinates.map(
        (c: [number, number]) => [c[1], c[0]] as [number, number],
      );
    }
    return null;
  } catch {
    return null;
  }
}

// Like fetchOsrmRoute but also returns distance (m) and duration (s)
async function fetchOsrmRouteWithInfo(
  from: [number, number],
  to: [number, number],
  signal?: AbortSignal,
): Promise<{
  coords: [number, number][];
  distance: number;
  duration: number;
} | null> {
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${from[1]},${from[0]};${to[1]},${to[0]}?overview=full&geometries=geojson`;
    const r = await fetch(url, { signal });
    const data = await r.json();
    if (data.routes?.length > 0) {
      const route = data.routes[0];
      const coords = route.geometry.coordinates.map(
        (c: [number, number]) => [c[1], c[0]] as [number, number],
      );
      return { coords, distance: route.distance, duration: route.duration };
    }
    return null;
  } catch {
    return null;
  }
}

async function reverseGeocode(lat: number, lng: number): Promise<string> {
  try {
    const r = await fetch(
      `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`,
    );
    const d = await r.json();
    const parts = (d.display_name as string)?.split(",");
    return parts ? parts.slice(0, 2).join(", ").trim() : "Pinned location";
  } catch {
    return "Pinned location";
  }
}

