type MapFocus = { coords: [number, number] | "route"; key: number } | null;

function MapAutoSize() {
  const map = useMap();
  useEffect(() => {
    const observer = new ResizeObserver(() => map.invalidateSize());
    observer.observe(map.getContainer());
    return () => observer.disconnect();
  }, [map]);
  return null;
}

function MapBounds({
  mapFocus,
  routeCoords,
}: {
  mapFocus: MapFocus;
  routeCoords: [number, number][] | null;
}) {
  const map = useMap();
  const userInteracted = useRef(false);

  // Any manual pan/zoom locks out auto-centering until next explicit selection
  useMapEvents({
    dragstart: () => {
      userInteracted.current = true;
    },
    zoomstart: () => {
      userInteracted.current = true;
    },
  });

  useEffect(() => {
    if (!mapFocus) return;
    // Explicit location selection always overrides user interaction
    userInteracted.current = false;

    try {
      const size = map.getSize();
      if (!size || size.x === 0 || size.y === 0) return;
      if (mapFocus.coords === "route" && routeCoords && routeCoords.length > 0) {
        map.fitBounds(L.latLngBounds(routeCoords), {
          padding: [80, 80],
          animate: true,
        });
      } else if (mapFocus.coords !== "route") {
        const c = mapFocus.coords as [number, number];
        if (isNaN(c[0]) || isNaN(c[1])) return;
        map.flyTo(c, 16, { animate: true, duration: 0.8 });
      }
    } catch {
      // Swallow projection errors
    }
    // Only key changes trigger this — GPS ticks never touch mapFocus so they never move the camera
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mapFocus?.key]);

  return null;
}

// Smooth-pan to a moving position; stops when user drags or zooms; resetKey re-enables follow
function MapSmoothFollow({
  position,
  resetKey = 0,
}: {
  position: [number, number] | null;
  resetKey?: number;
}) {
  const map = useMap();
  const userInteracted = useRef(false);

  useMapEvents({
    dragstart: () => {
      userInteracted.current = true;
    },
    zoomstart: () => {
      userInteracted.current = true;
    },
  });

  useEffect(() => {
    userInteracted.current = false;
  }, [resetKey]);

  useEffect(() => {
    if (!position || userInteracted.current) return;
    map.panTo(position, { animate: true, duration: 0.6 });
  }, [position, map]);

  return null;
}

// Fly the map to the rider's first broadcast location so the passenger immediately
// sees where the rider actually is, instead of staying centered on the pickup point.
function FlyToFirstRiderLocation({
  riderLocation,
}: {
  riderLocation: [number, number] | null;
}) {
  const map = useMap();
  const hasFlewRef = useRef(false);

  useEffect(() => {
    if (!riderLocation || hasFlewRef.current) return;
    hasFlewRef.current = true;
    map.flyTo(riderLocation, 15, { animate: true, duration: 1.2 });
  }, [riderLocation, map]);

  return null;
}

// Fly map to a single coordinate (used for errand location pin updates)
function MapFlyTo({ coords }: { coords: [number, number] | null }) {
  const map = useMap();
  const valid = coords != null && !isNaN(coords[0]) && !isNaN(coords[1]);
  const key = valid ? `${coords![0]},${coords![1]}` : "";
  useEffect(() => {
    if (!valid || !key) return;
    try {
      // Guard: skip if the map container has zero dimensions (e.g. md:hidden)
      const size = map.getSize();
      if (!size || size.x === 0 || size.y === 0) return;
      map.flyTo(coords!, 16, { animate: true, duration: 0.8 });
    } catch {
      // Swallow any projection errors (0-size container, not yet initialised)
    }
  }, [key]);
  return null;
}

// Fit map bounds to show both errand pickup and dropoff markers
function ErrandMapFit({ pickup, dropoff }: { pickup: [number, number]; dropoff: [number, number] }) {
  const map = useMap();
  const key = `${pickup[0]},${pickup[1]},${dropoff[0]},${dropoff[1]}`;
  useEffect(() => {
    if (isNaN(pickup[0]) || isNaN(pickup[1]) || isNaN(dropoff[0]) || isNaN(dropoff[1])) return;
    try {
      const size = map.getSize();
      if (!size || size.x === 0 || size.y === 0) return;
      map.fitBounds(L.latLngBounds([pickup, dropoff]), { padding: [60, 60], maxZoom: 15, animate: true });
    } catch { /* hidden or not yet initialised */ }
  }, [key]);
  return null;
}

// Zoom control at a custom corner (avoids conflicts with existing UI)
function MapZoomControl({
  position = "bottomright",
}: {
  position?: "topright" | "bottomright" | "topleft" | "bottomleft";
}) {
  const map = useMap();
  useEffect(() => {
    const ctrl = L.control.zoom({ position });
    ctrl.addTo(map);
    return () => {
      ctrl.remove();
    };
  }, [map, position]);
  return null;
}

